#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int MAXN = 210;
const int MAXM = 1000007;

int n, T;
char s1[15][15], s2[15][15];
int id[15][15], cnt;
int s, t;
int xz, yz;
int dir[4][2] = { {0,1}, {0,-1}, {1,0}, {-1,0} };

bool inside(int x, int y) {
    return x >= 0 && y >= 0 && x < n && y < n && s1[x][y] >= '0' && s1[x][y] <= '9';
}

int vv[MAXM], cap[MAXM], nxt[MAXM], h[MAXN], e = 0;
int pre[MAXN], vis[MAXN];

void add_edge(int u, int v, int c) {
    vv[e] = v; cap[e] = c; nxt[e] = h[u]; h[u] = e++;
    vv[e] = u; cap[e] = 0; nxt[e] = h[v]; h[v] = e++;
}

int maxFlow() {
    int totalFlow = 0;
    while (true) {
        memset(pre, -1, sizeof(pre));
        memset(vis, 0, sizeof(vis));
        queue<int> q;
        q.push(s);
        vis[s] = 1;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int i = h[u]; i != -1; i = nxt[i]) {
                int v = vv[i];
                if (cap[i] > 0 && !vis[v]) {
                    vis[v] = 1;
                    pre[v] = i;
                    if (v == t) goto augment;
                    q.push(v);
                }
            }
        }
        break;
        augment:
        int flow = 1e9;
        for (int v = t; v != s; v = vv[pre[v] ^ 1]) {
            flow = min(flow, cap[pre[v]]);
        }
        for (int v = t; v != s; v = vv[pre[v] ^ 1]) {
            cap[pre[v]] -= flow;
            cap[pre[v] ^ 1] += flow;
        }
        totalFlow += flow;
    }
    return totalFlow;
}

int main() {
    cin >> n >> T;
    for (int i = 0; i < n; ++i) cin >> s1[i];
    for (int i = 0; i < n; ++i) cin >> s2[i];

    memset(h, -1, sizeof(h));
    e = 0;
    memset(id, -1, sizeof(id));
    cnt = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (s1[i][j] == 'Z') {
                xz = i; yz = j;
            } else if (inside(i, j)) {
                id[i][j] = ++cnt;
            }
        }
    s = 0; t = 2 * cnt + 1;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (inside(i, j))
                for (int d = 0; d < 4; ++d) {
                    int x = i + dir[d][0], y = j + dir[d][1];
                    if (inside(x, y)) {
                        if (s2[x][y] != 0) {
                            add_edge(id[i][j] + cnt, t, s2[x][y] - '0');
                        }
                        if (s1[i][j] == '0') continue;
                        add_edge(s, id[i][j], s1[i][j] - '0');
                        if (s2[x][y] != 0) {
                            add_edge(id[i][j], id[x][y] + cnt, 10);
                        }
                    }
                }
    cout << maxFlow() << endl;
    return 0;
}
